    // 上（yRatio=0）が120dB、下（yRatio=1）が-10dB
    let dBraw = Y_MIN + (yRatio * yRange);
    dBraw += CAL_OFFSET_DB; // optional small offset (kept 0 by default)
    const dBclamped = clamp(round5(dBraw), Y_MIN, Y_MAX);

