import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { supabase, isSupabaseDisabled } from './supabaseClient';
import {
  fetchAllUsageEvents,
  usageEventTypeLabel,
  formatUsageMetadataPreview,
  USAGE_EVENT,
  DEFAULT_PRESET_KEYS,
  countPresetCompletions,
  averageAccuracyForPresets,
} from './usageEvents';
import InstructorCaseGenerator from './InstructorCaseGenerator';

export default function InstructorDashboard({ instructor, onLogout }) {
  const [mainTab, setMainTab] = useState('generate');
  const [students, setStudents] = useState([]);
  const [stats, setStats] = useState({
    totalStudents: 0,
    activeStudents: 0,
    averageAccuracy: 0,
    totalPresetCompletions: 0,
    totalClinicalGenerations: 0,
    todayActivity: 0,
  });
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 50;
  const [usageEvents, setUsageEvents] = useState([]);
  const [usageEventsLoading, setUsageEventsLoading] = useState(false);
  const [usageSearch, setUsageSearch] = useState('');
  const [usageTypeFilter, setUsageTypeFilter] = useState('all');

  /** 学生・進捗のみ（手動更新時に取得。使用履歴は含めない） */
  const loadStudentsData = useCallback(async () => {
    setIsLoading(true);
    try {
      // 全学生を取得
      const { data: studentsData, error: studentsError } = await supabase
        .from('students')
        .select('*')
        .order('created_at', { ascending: false });

      if (studentsError) {
        console.error('学生データの取得エラー:', studentsError);
        setIsLoading(false);
        return;
      }

      // 各学生の進捗データを取得
      const studentsWithProgress = await Promise.all(
        (studentsData || []).map(async (student) => {
          const { data: progressData } = await supabase
            .from('student_progress')
            .select('*')
            .eq('student_id', student.student_id)
            .single();

          let progress = null;
          if (progressData && progressData.progress_data) {
            try {
              progress = typeof progressData.progress_data === 'string'
                ? JSON.parse(progressData.progress_data)
                : progressData.progress_data;
            } catch (e) {
              console.error('進捗データのパースエラー:', e);
            }
          }

          return {
            ...student,
            progress,
            lastProgressUpdate: progressData?.updated_at || null,
          };
        })
      );

      setStudents(studentsWithProgress);

      // 統計を計算
      const now = new Date();
      const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());

      const activeStudents = studentsWithProgress.filter(s => {
        if (!s.lastProgressUpdate) return false;
        const lastUpdate = new Date(s.lastProgressUpdate);
        return lastUpdate >= sevenDaysAgo;
      }).length;

      const todayActivity = studentsWithProgress.filter(s => {
        if (!s.lastProgressUpdate) return false;
        const lastUpdate = new Date(s.lastProgressUpdate);
        return lastUpdate >= todayStart;
      }).length;

      const studentsWithPresetAccuracy = studentsWithProgress.filter((s) => {
        const ca = s.progress?.caseAccuracy;
        if (!ca) return false;
        return DEFAULT_PRESET_KEYS.some((k) => ca[k] != null);
      });

      const averageAccuracy = studentsWithPresetAccuracy.length > 0
        ? Math.round(
            studentsWithPresetAccuracy.reduce(
              (sum, s) => sum + averageAccuracyForPresets(s.progress),
              0
            ) / studentsWithPresetAccuracy.length
          )
        : 0;

      const totalPresetCompletions = studentsWithProgress.reduce(
        (sum, s) => sum + countPresetCompletions(s.progress),
        0
      );

      setStats((prev) => ({
        totalStudents: studentsWithProgress.length,
        activeStudents,
        averageAccuracy,
        totalPresetCompletions,
        totalClinicalGenerations: prev.totalClinicalGenerations,
        todayActivity,
      }));
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  /** 使用履歴ログ（初回表示・手動更新時のみ。自動ポーリングしない） */
  const loadUsageEvents = useCallback(async () => {
    if (isSupabaseDisabled) return;
    setUsageEventsLoading(true);
    try {
      const { data: usageData, error: usageErr } = await fetchAllUsageEvents(2000);
      const totalClinicalGenerations =
        !usageErr && usageData
          ? usageData.filter((e) => e.event_type === USAGE_EVENT.CLINICAL_CASE_GENERATION).length
          : 0;

      if (!usageErr && usageData) {
        setUsageEvents(usageData);
      } else if (usageErr) {
        console.warn('使用履歴の取得:', usageErr);
      }

      setStats((prev) => ({
        ...prev,
        totalClinicalGenerations,
      }));
    } catch (error) {
      console.error('使用履歴の読み込みエラー:', error);
    } finally {
      setUsageEventsLoading(false);
    }
  }, []);

  const loadAllData = useCallback(async () => {
    await loadStudentsData();
    await loadUsageEvents();
  }, [loadStudentsData, loadUsageEvents]);

  useEffect(() => {
    loadStudentsData();
    loadUsageEvents();
  }, [loadStudentsData, loadUsageEvents]);

  // フィルタリング
  const filteredStudents = students.filter(student =>
    student.student_id.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredUsageEvents = usageEvents.filter((ev) => {
    const matchSearch =
      !usageSearch.trim() ||
      String(ev.student_id || '').toLowerCase().includes(usageSearch.trim().toLowerCase());
    const matchType = usageTypeFilter === 'all' || ev.event_type === usageTypeFilter;
    return matchSearch && matchType;
  });

  const clinicalUsageCount = usageEvents.filter(
    (ev) => ev.event_type === USAGE_EVENT.CLINICAL_CASE_GENERATION
  ).length;

  /** 学生ID →「臨床症例の生成」使用履歴の件数（ログイン時の自動生成のみ蓄積） */
  const clinicalGenByStudent = useMemo(() => {
    const m = new Map();
    for (const ev of usageEvents) {
      if (ev.event_type === USAGE_EVENT.CLINICAL_CASE_GENERATION && ev.student_id) {
        m.set(ev.student_id, (m.get(ev.student_id) || 0) + 1);
      }
    }
    return m;
  }, [usageEvents]);

  // CSVエクスポート
  const exportToCSV = () => {
    const headers = [
      '学生ID',
      '登録日',
      '最終ログイン',
      'プリセット完了数(A〜H)',
      'プリセット総数',
      '臨床症例生成ログ回数',
      'プリセット平均精度',
      '総セッション数',
    ];
    const rows = filteredStudents.map((student) => {
      const presetDone = countPresetCompletions(student.progress);
      const totalPreset = DEFAULT_PRESET_KEYS.length;
      const clinicalCount = clinicalGenByStudent.get(student.student_id) || 0;
      const avgAccuracy = averageAccuracyForPresets(student.progress);

      return [
        student.student_id,
        new Date(student.created_at).toLocaleDateString('ja-JP'),
        student.lastProgressUpdate ? new Date(student.lastProgressUpdate).toLocaleDateString('ja-JP') : '未ログイン',
        presetDone,
        totalPreset,
        clinicalCount,
        `${avgAccuracy}%`,
        student.progress?.totalSessions || 0,
      ];
    });

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `students_progress_${new Date().toISOString().slice(0, 10)}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // ページネーション
  const totalPages = Math.ceil(filteredStudents.length / itemsPerPage);
  const paginatedStudents = filteredStudents.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  // 学生詳細の表示
  const showStudentDetail = (student) => {
    setSelectedStudent(student);
  };

  // 進捗リセット
  const resetStudentProgress = async (studentId) => {
    if (!window.confirm(`学生ID: ${studentId} の進捗をリセットしますか？この操作は取り消せません。`)) {
      return;
    }

    try {
      const { error } = await supabase
        .from('student_progress')
        .delete()
        .eq('student_id', studentId);

      if (error) throw error;

      alert('進捗データをリセットしました');
      loadStudentsData();
      setSelectedStudent(null);
    } catch (error) {
      console.error('リセットエラー:', error);
      alert('進捗データのリセットに失敗しました');
    }
  };

  return (
    <div className="w-full min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* ヘッダー */}
        <header className="bg-white rounded-2xl shadow p-6 mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">Audioscope EDU - 講師用ダッシュボード</h1>
              <p className="text-sm text-gray-600 mt-1">講師: {instructor.name}</p>
              <p className="text-xs text-gray-500 mt-0.5">学生データ・使用履歴は自動更新されません。「更新」で最新を取得してください。</p>
            </div>
            <div className="flex items-center gap-4">
              <button
                onClick={loadAllData}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                disabled={isLoading || usageEventsLoading}
              >
                {isLoading || usageEventsLoading ? '更新中...' : '🔄 更新'}
              </button>
              <button
                onClick={onLogout}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300"
              >
                ログアウト
              </button>
            </div>
          </div>
        </header>

        <div className="grid grid-cols-2 gap-2 mb-6 bg-white rounded-2xl shadow p-2">
          <button
            type="button"
            onClick={() => setMainTab('generate')}
            className={`px-4 py-3 rounded-xl text-base font-semibold ${mainTab === 'generate' ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
          >
            教材生成
          </button>
          <button
            type="button"
            onClick={() => setMainTab('progress')}
            className={`px-4 py-3 rounded-xl text-base font-semibold ${mainTab === 'progress' ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
          >
            学生の進捗
          </button>
        </div>

        {mainTab === 'generate' && (
          <InstructorCaseGenerator />
        )}

        {mainTab === 'progress' && (
        <>
        {/* 統計カード */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
          <div className="bg-blue-50 rounded-xl p-5 border border-blue-200">
            <div className="text-sm text-blue-600 font-medium mb-1">総学生数</div>
            <div className="text-3xl font-bold text-blue-800">{stats.totalStudents}</div>
          </div>
          <div className="bg-green-50 rounded-xl p-5 border border-green-200">
            <div className="text-sm text-green-600 font-medium mb-1">アクティブ学生</div>
            <div className="text-3xl font-bold text-green-800">{stats.activeStudents}</div>
            <div className="text-xs text-green-600 mt-1">過去7日以内</div>
          </div>
          <div className="bg-orange-50 rounded-xl p-5 border border-orange-200">
            <div className="text-sm text-orange-600 font-medium mb-1">平均精度（プリセット）</div>
            <div className="text-3xl font-bold text-orange-800">{stats.averageAccuracy}%</div>
            <div className="text-xs text-orange-600 mt-1">症例A〜Hのみ</div>
          </div>
          <div className="bg-purple-50 rounded-xl p-5 border border-purple-200">
            <div className="text-sm text-purple-600 font-medium mb-1">プリセット完了（累計）</div>
            <div className="text-3xl font-bold text-purple-800">{stats.totalPresetCompletions}</div>
            <div className="text-xs text-purple-600 mt-1">A〜H の完了登録の合計</div>
          </div>
          <div className="bg-teal-50 rounded-xl p-5 border border-teal-200">
            <div className="text-sm text-teal-600 font-medium mb-1">臨床症例の生成ログ</div>
            <div className="text-3xl font-bold text-teal-800">{stats.totalClinicalGenerations}</div>
            <div className="text-xs text-teal-600 mt-1">取得件数内・全学生</div>
          </div>
          <div className="bg-indigo-50 rounded-xl p-5 border border-indigo-200">
            <div className="text-sm text-indigo-600 font-medium mb-1">本日の活動</div>
            <div className="text-3xl font-bold text-indigo-800">{stats.todayActivity}</div>
            <div className="text-xs text-indigo-600 mt-1">進捗更新があった学生数</div>
          </div>
        </div>

        {/* 検索・エクスポートバー */}
        <div className="bg-white rounded-2xl shadow p-4 mb-6">
          <div className="flex items-center gap-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="🔍 学生IDで検索..."
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  setCurrentPage(1);
                }}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <button
              onClick={exportToCSV}
              className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center gap-2"
            >
              <span>📥</span>
              <span>CSV出力</span>
            </button>
          </div>
        </div>

        {/* 使用履歴（全学生） */}
        <div className="bg-white rounded-2xl shadow p-4 mb-6">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3 mb-3">
            <div>
              <h2 className="text-lg font-semibold text-gray-900">使用履歴ログ</h2>
              <p className="text-xs text-gray-500 mt-1">
                プリセット症例の進捗に加え、学生が「臨床症例生成」を実行した記録（臨床症例の生成）もここに表示されます（学生ログイン時）。
                履歴は自動更新されません。最新を見るときは「履歴を更新」またはヘッダーの「更新」を押してください。
              </p>
            </div>
            <div className="flex flex-col sm:flex-row gap-2 w-full md:w-auto md:items-center">
              <button
                type="button"
                onClick={loadUsageEvents}
                disabled={usageEventsLoading || isSupabaseDisabled}
                className="px-3 py-2 border border-gray-300 rounded-lg text-sm bg-white hover:bg-gray-50 disabled:opacity-50 whitespace-nowrap"
              >
                {usageEventsLoading ? '読込中…' : '履歴を更新'}
              </button>
              <select
                value={usageTypeFilter}
                onChange={(e) => setUsageTypeFilter(e.target.value)}
                className="w-full sm:w-48 px-3 py-2 border border-gray-300 rounded-lg text-sm bg-white"
                aria-label="使用履歴の種別で絞り込み"
              >
                <option value="all">種別: すべて</option>
                <option value={USAGE_EVENT.LOGIN}>ログイン</option>
                <option value={USAGE_EVENT.DEFAULT_CASE_PROGRESS}>デフォルト症例の進捗</option>
                <option value={USAGE_EVENT.CLINICAL_CASE_GENERATION}>臨床症例の生成</option>
              </select>
              <input
                type="text"
                placeholder="学生IDで絞り込み..."
                value={usageSearch}
                onChange={(e) => setUsageSearch(e.target.value)}
                className="w-full md:w-64 px-3 py-2 border border-gray-300 rounded-lg text-sm"
              />
            </div>
          </div>
          {!isSupabaseDisabled && (
            <p
              className={`text-xs rounded-lg px-3 py-2 mb-3 border ${
                clinicalUsageCount > 0
                  ? 'text-teal-800 bg-teal-50 border-teal-100'
                  : 'text-gray-700 bg-gray-50 border-gray-200'
              }`}
            >
              臨床症例の生成ログ: <span className="font-semibold">{clinicalUsageCount}</span> 件（取得件数内）
              {clinicalUsageCount === 0 && (
                <span className="block mt-1.5 text-gray-600">
                  まだ誰も生成していないか、ログイン前に生成していると件数は増えません。行が増えるのはログイン後に「臨床症例生成」を押したときだけです。
                </span>
              )}
            </p>
          )}
          {isSupabaseDisabled ? (
            <p className="text-sm text-gray-500">Supabase が無効のため、使用履歴は取得できません。</p>
          ) : filteredUsageEvents.length === 0 ? (
            <p className="text-sm text-gray-500">
              {usageEvents.length === 0
                ? 'まだ使用履歴はありません。学生がログイン・学習を開始すると、ここに履歴が表示されます。'
                : usageTypeFilter === USAGE_EVENT.CLINICAL_CASE_GENERATION
                  ? '臨床症例の生成ログはまだありません。種別を「すべて」にすると、ログインやプリセット進捗の記録は表示されます。'
                  : '該当する履歴がありません。種別または学生IDの条件を変えてください。'}
            </p>
          ) : (
            <div className="overflow-x-auto max-h-96 overflow-y-auto text-sm">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="text-left text-gray-600 border-b">
                    <th className="py-2 pr-2">日時</th>
                    <th className="py-2 pr-2">学生ID</th>
                    <th className="py-2 pr-2">種別</th>
                    <th className="py-2">概要</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredUsageEvents.map((row) => (
                    <tr key={row.id} className="border-b border-gray-100">
                      <td className="py-2 pr-2 whitespace-nowrap">
                        {row.created_at ? new Date(row.created_at).toLocaleString('ja-JP') : '—'}
                      </td>
                      <td className="py-2 pr-2 font-medium">{row.student_id}</td>
                      <td className="py-2 pr-2">{usageEventTypeLabel(row.event_type)}</td>
                      <td className="py-2 text-gray-700 break-all">{formatUsageMetadataPreview(row)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* 学生一覧テーブル */}
        <div className="bg-white rounded-2xl shadow overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">学生ID</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    プリセット完了
                    <span className="block font-normal normal-case text-gray-400">A〜H</span>
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    臨床生成
                    <span className="block font-normal normal-case text-gray-400">ログ回数</span>
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    平均精度
                    <span className="block font-normal normal-case text-gray-400">プリセット</span>
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">総セッション</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">最終ログイン</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">アクション</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {isLoading ? (
                  <tr>
                    <td colSpan="7" className="px-6 py-8 text-center text-gray-500">
                      データを読み込んでいます...
                    </td>
                  </tr>
                ) : paginatedStudents.length === 0 ? (
                  <tr>
                    <td colSpan="7" className="px-6 py-8 text-center text-gray-500">
                      {searchTerm ? '検索結果が見つかりませんでした' : '学生データがありません'}
                    </td>
                  </tr>
                ) : (
                  paginatedStudents.map((student) => {
                    const presetDone = countPresetCompletions(student.progress);
                    const totalPreset = DEFAULT_PRESET_KEYS.length;
                    const clinicalCount = clinicalGenByStudent.get(student.student_id) || 0;
                    const avgAccuracy = averageAccuracyForPresets(student.progress);

                    return (
                      <tr key={student.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm font-medium text-gray-900">{student.student_id}</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm text-gray-900">
                            {presetDone}/{totalPreset}
                          </div>
                          <div className="w-32 bg-gray-200 rounded-full h-2 mt-1">
                            <div
                              className="bg-blue-600 h-2 rounded-full"
                              style={{ width: `${(presetDone / totalPreset) * 100}%` }}
                            />
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm font-medium text-gray-900">{clinicalCount}</div>
                          <div className="text-xs text-gray-500">臨床症例の生成</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className={`text-sm font-semibold ${
                            avgAccuracy >= 90 ? 'text-green-600' :
                            avgAccuracy >= 70 ? 'text-yellow-600' : 'text-red-600'
                          }`}>
                            {avgAccuracy}%
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm text-gray-900">
                            {student.progress?.totalSessions || 0}
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm text-gray-900">
                            {student.lastProgressUpdate
                              ? new Date(student.lastProgressUpdate).toLocaleString('ja-JP')
                              : '未ログイン'}
                          </div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                          <button
                            onClick={() => showStudentDetail(student)}
                            className="text-blue-600 hover:text-blue-900 mr-3"
                          >
                            詳細
                          </button>
                          <button
                            onClick={() => resetStudentProgress(student.student_id)}
                            className="text-red-600 hover:text-red-900"
                          >
                            リセット
                          </button>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* ページネーション */}
          {totalPages > 1 && (
            <div className="bg-gray-50 px-6 py-4 flex items-center justify-between border-t border-gray-200">
              <div className="text-sm text-gray-700">
                {filteredStudents.length}件中 {(currentPage - 1) * itemsPerPage + 1}-
                {Math.min(currentPage * itemsPerPage, filteredStudents.length)}件を表示
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="px-3 py-1 border rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  前へ
                </button>
                <span className="px-3 py-1 text-sm">
                  {currentPage} / {totalPages}
                </span>
                <button
                  onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                  disabled={currentPage === totalPages}
                  className="px-3 py-1 border rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  次へ
                </button>
              </div>
            </div>
          )}
        </div>
        </>
        )}

      </div>

      {/* 学生詳細モーダル */}
      {selectedStudent && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-2xl font-bold text-gray-900">
                  学生詳細: {selectedStudent.student_id}
                </h2>
                <button
                  onClick={() => setSelectedStudent(null)}
                  className="text-gray-400 hover:text-gray-600 text-2xl"
                >
                  ×
                </button>
              </div>

              <div className="space-y-6">
                {/* 基本情報 */}
                <div className="bg-gray-50 rounded-lg p-4">
                  <h3 className="font-semibold text-gray-800 mb-3">基本情報</h3>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <span className="text-gray-600">登録日:</span>{' '}
                      <span className="font-medium">
                        {new Date(selectedStudent.created_at).toLocaleString('ja-JP')}
                      </span>
                    </div>
                    <div>
                      <span className="text-gray-600">最終ログイン:</span>{' '}
                      <span className="font-medium">
                        {selectedStudent.lastProgressUpdate
                          ? new Date(selectedStudent.lastProgressUpdate).toLocaleString('ja-JP')
                          : '未ログイン'}
                      </span>
                    </div>
                  </div>
                </div>

                {/* 進捗詳細 */}
                {selectedStudent.progress && (
                  <>
                    <div className="bg-blue-50 rounded-lg p-4">
                      <h3 className="font-semibold text-gray-800 mb-3">進捗サマリー</h3>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm">
                        <div>
                          <span className="text-gray-600">総セッション数:</span>{' '}
                          <span className="font-medium">{selectedStudent.progress.totalSessions || 0}</span>
                        </div>
                        <div>
                          <span className="text-gray-600">プリセット完了（A〜H）:</span>{' '}
                          <span className="font-medium">
                            {countPresetCompletions(selectedStudent.progress)}/{DEFAULT_PRESET_KEYS.length}
                          </span>
                        </div>
                        <div>
                          <span className="text-gray-600">臨床症例の生成（ログ）:</span>{' '}
                          <span className="font-medium">
                            {clinicalGenByStudent.get(selectedStudent.student_id) || 0} 回
                          </span>
                          <span className="text-gray-500 text-xs block mt-0.5">
                            使用履歴の「臨床症例の生成」件数です
                          </span>
                        </div>
                        <div>
                          <span className="text-gray-600">最終セッション:</span>{' '}
                          <span className="font-medium">
                            {selectedStudent.progress.lastSessionDate
                              ? new Date(selectedStudent.progress.lastSessionDate).toLocaleDateString('ja-JP')
                              : '未実施'}
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* 症例別進捗 */}
                    {selectedStudent.progress.caseAccuracy && Object.keys(selectedStudent.progress.caseAccuracy).length > 0 && (
                      <div className="bg-green-50 rounded-lg p-4">
                        <h3 className="font-semibold text-gray-800 mb-3">プリセット症例別進捗（A〜H）</h3>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                          {['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'].map(caseId => {
                            const caseData = selectedStudent.progress.caseAccuracy[caseId];
                            const isCompleted = selectedStudent.progress.completedCases?.includes(caseId);

                            return (
                              <div
                                key={caseId}
                                className={`p-3 rounded-lg border text-center ${
                                  isCompleted
                                    ? 'bg-white border-green-300'
                                    : 'bg-gray-100 border-gray-300'
                                }`}
                              >
                                <div className="font-semibold text-gray-800">症例{caseId}</div>
                                {isCompleted && caseData ? (
                                  <>
                                    <div className="text-lg font-bold text-green-600 mt-1">
                                      {caseData.accuracy}%
                                    </div>
                                    <div className="text-xs text-gray-600 mt-1">
                                      {caseData.correct}/{caseData.total}
                                    </div>
                                    {caseData.completedAt && (
                                      <div className="text-xs text-gray-500 mt-1">
                                        {new Date(caseData.completedAt).toLocaleDateString('ja-JP')}
                                      </div>
                                    )}
                                  </>
                                ) : (
                                  <div className="text-sm text-gray-500 mt-1">未完了</div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </>
                )}

                {!selectedStudent.progress && (
                  <div className="bg-yellow-50 rounded-lg p-4 text-center text-gray-600">
                    進捗データがありません
                  </div>
                )}

                {/* この学生の使用履歴 */}
                {!isSupabaseDisabled && (
                  <div className="bg-gray-50 rounded-lg p-4">
                    <h3 className="font-semibold text-gray-800 mb-3">使用履歴（この学生）</h3>
                    {(() => {
                      const evs = usageEvents
                        .filter((e) => e.student_id === selectedStudent.student_id)
                        .slice(0, 40);
                      if (evs.length === 0) {
                        return <p className="text-sm text-gray-600">記録がありません</p>;
                      }
                      return (
                        <div className="overflow-x-auto max-h-56 overflow-y-auto text-xs">
                          <table className="w-full border-collapse">
                            <thead>
                              <tr className="text-left text-gray-600 border-b">
                                <th className="py-1 pr-2">日時</th>
                                <th className="py-1 pr-2">種別</th>
                                <th className="py-1">概要</th>
                              </tr>
                            </thead>
                            <tbody>
                              {evs.map((row) => (
                                <tr key={row.id} className="border-b border-gray-200">
                                  <td className="py-1 pr-2 whitespace-nowrap">
                                    {row.created_at ? new Date(row.created_at).toLocaleString('ja-JP') : '—'}
                                  </td>
                                  <td className="py-1 pr-2">{usageEventTypeLabel(row.event_type)}</td>
                                  <td className="py-1 break-all">{formatUsageMetadataPreview(row)}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      );
                    })()}
                  </div>
                )}
              </div>

              <div className="mt-6 flex justify-end gap-3">
                <button
                  onClick={() => resetStudentProgress(selectedStudent.student_id)}
                  className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
                >
                  進捗をリセット
                </button>
                <button
                  onClick={() => setSelectedStudent(null)}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300"
                >
                  閉じる
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}








